import java.util.ArrayList;
import java.util.List;

class Completed {

    public List<String> fullJustify(String[] words, int maxWidth) {

        List<String> result = new ArrayList<>();
        int index = 0;

        while (index < words.length) {

            int lineLength = words[index].length();
            int last = index + 1;

            while (last < words.length
                && lineLength + 1 + words[last].length() <= maxWidth) {

                lineLength += 1 + words[last].length();
                last++;
            }

            StringBuilder line = new StringBuilder();
            int wordCount = last - index;
            boolean isLastLine = last == words.length;

            if (wordCount == 1 || isLastLine) {

                for (int i = index; i < last; i++) {

                    line.append(words[i]);

                    if (i < last - 1) {
                        line.append(' ');
                    }
                }

                while (line.length() < maxWidth) {
                    line.append(' ');
                }
            } else {

                int totalChars = 0;

                for (int i = index; i < last; i++) {
                    totalChars += words[i].length();
                }

                int totalSpaces = maxWidth - totalChars;
                int gaps = wordCount - 1;
                int spaceWidth = totalSpaces / gaps;
                int extra = totalSpaces % gaps;

                for (int i = index; i < last; i++) {

                    line.append(words[i]);

                    if (i < last - 1) {

                        int spaces = spaceWidth + (extra > 0 ? 1 : 0);

                        if (extra > 0) {
                            extra--;
                        }

                        for (int s = 0; s < spaces; s++) {
                            line.append(' ');
                        }
                    }
                }
            }

            result.add(line.toString());
            index = last;
        }

        return result;
    }
}

